package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsFoodChain {
 @GameTest(template="empty") public static void privateHarvestIsCollectedBeforeRealDeficit(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var p=f.r.state.people.values().stream().filter(v->v.role==RuralRules.Role.FARMER&&f.village.residents.contains(v.id)).findFirst().orElseThrow();var family=f.r.state.families.get(p.family);var stocks=f.r.stocks(family.id);for(var stock:stocks){stock.wheat=stock.bread=0;RuralMeat.clear(stock);}int need=DataCityRules.foodReserve(RuralRules.demand(family,f.r.state.people),3);p.cropTicks=35000;p.productionCredit=28;p.pendingWheat=0;h.assertTrue(RuralStaples.deficit(f.r,family,stocks)==need,"Unripe future grain cannot pay for the next meal");p.pendingWheat=need;p.pendingAge.add(need,.5);long money=f.t.money(f.s),grain=f.t.grain(f.s),harvest=f.r.state.wheatProduced;h.assertTrue(RuralStaples.collect(f.r,family,stocks)==need&&RuralStaples.deficit(f.r,family,stocks)==0,"Actual mature private grain removes the purchase deficit without buying to capacity");h.assertTrue(f.t.money(f.s)==money&&f.t.grain(f.s)==grain&&f.r.state.wheatProduced==harvest+need&&p.pendingWheat==0,"Harvest counted once, existing money and food conserved");h.assertTrue(RuralStaples.collect(f.r,family,stocks)==0,"Repeated collection cannot duplicate crops");}h.succeed();}
 @GameTest(template="empty") public static void idleHouseholdCanComparePreparedFood(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var family=f.r.state.families.values().stream().filter(v->v.city.equals(f.city.id)).findFirst().orElseThrow();var baker=f.t.state.businesses.values().stream().filter(v->v.city.equals(f.city.id)&&v.kind.equals("baker")).findFirst().orElseThrow();baker.listed[1].add(192,19200);h.assertTrue(CityOpportunities.buyPrepared(f.s,family,false),"Idle or dedicated cook can choose prepared food when real bread quote is cheaper than grain");baker.listed[1]=new TradeRules.Lot();h.assertTrue(!CityOpportunities.buyPrepared(f.s,family,false),"No observed productive income means expensive prepared food is not forced");}h.succeed();}
 @GameTest(template="empty") public static void sharedHomeMaterialsUseFamilyMoneyButKeepFood(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var family=d.state.families.get(f.person.family);UUID other=UUID.randomUUID();f.city.residents.add(other);var p=d.enroll(f.server,f.city,other,"同户成员");d.state.families.get(p.family).members.remove(other);p.family=family.id;family.members.add(other);f.house.owner=f.worker;f.house.personal=true;f.house.beds=2;f.house.residents.add(f.worker);f.house.residents.add(other);var e=CityEconomy.get(f.server);e.state.accounts.put(CityEconomy.person(f.worker),0L);long reserve=CityWorksFinance.protectedFood(f.server,f.worker);e.state.accounts.put(CityEconomy.person(other),reserve+1);var q=new CityHousing.Material();q.stock=2;q.priceCents=100;f.city.housing.market.put("minecraft:oak_planks",q);long total=f.money();h.assertTrue(CityWorksFinance.canMaterial(f.server,f.city,f.house,Blocks.OAK_PLANKS.defaultBlockState(),false,null),"Owner zero, shared resident has real excess funds");h.assertTrue(CityWorksFinance.material(f.server,f.city,f.house,Blocks.OAK_PLANKS.defaultBlockState(),false)&&q.stock==1,"One actual material paid by household member");h.assertTrue(f.money()==total&&e.balance(CityEconomy.person(other))==reserve&&f.house.owner.equals(f.worker),"No minting or ownership transfer; full food money remains");h.assertTrue(!CityWorksFinance.material(f.server,f.city,f.house,Blocks.OAK_PLANKS.defaultBlockState(),false)&&q.stock==1,"Cannot consume food reserve on repeated repair");}h.succeed();}
 @GameTest(template="empty") public static void sharedPaymentDoesNotReachOtherPropertiesOrPublicWork(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var family=d.state.families.get(f.person.family);UUID other=UUID.randomUUID();f.city.residents.add(other);var p=d.enroll(f.server,f.city,other,"同户非房主");d.state.families.get(p.family).members.remove(other);p.family=family.id;family.members.add(other);var e=CityEconomy.get(f.server);e.state.accounts.put(CityEconomy.person(f.worker),0L);e.state.accounts.put(CityEconomy.person(other),1000L);e.state.accounts.put(CityEconomy.treasury(f.city.id),0L);f.house.personal=true;f.house.owner=f.worker;f.house.beds=2;var q=new CityHousing.Material();q.stock=2;q.priceCents=100;f.city.housing.market.put("minecraft:oak_planks",q);h.assertTrue(!CityWorksFinance.material(f.server,f.city,f.house,Blocks.OAK_PLANKS.defaultBlockState(),false),"Family does not fund owner's unoccupied investment property");f.house.residents.add(f.worker);h.assertTrue(!CityWorksFinance.material(f.server,f.city,f.house,Blocks.OAK_PLANKS.defaultBlockState(),true),"Emergency public work cannot charge a private family");long reserve=CityWorksFinance.protectedFood(f.server,f.worker);e.state.accounts.put(CityEconomy.person(other),reserve+3);h.assertTrue(!CityWorksFinance.canMaterial(f.server,f.city,f.house,Blocks.OAK_PLANKS.defaultBlockState(),false,CityEconomy.person(other)),"Preflight deducts same-family pending wage before material eligibility");h.assertTrue(q.stock==2,"Rejected preflights and payments do not consume materials");}h.succeed();}
 @GameTest(template="empty") public static void preferredBreadIsBoughtBeforeRawGrain(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var family=f.r.state.families.values().stream().filter(v->v.city.equals(f.city.id)).findFirst().orElseThrow();var home=new FamilyLivelihood.Home();home.processor=family.members.getFirst();home.preferPrepared=true;f.t.state.households.put(family.id,home);var stores=f.r.stocks(family.id);for(var stock:stores){stock.wheat=stock.bread=0;RuralMeat.clear(stock);}var baker=f.t.state.businesses.values().stream().filter(v->v.city.equals(f.city.id)&&v.kind.equals("baker")).findFirst().orElseThrow();baker.listed[1].add(192,19200);long money=f.t.money(f.s),grain=f.t.grain(f.s);f.t.urbanCycle(f.s,f.city,false);h.assertTrue(RuralRules.count(stores,true)>0&&RuralRules.count(stores,false)==0,"Prepared choice produces a real bread order before raw grain occupies storage");h.assertTrue(f.t.money(f.s)==money&&f.t.grain(f.s)==grain,"Real bread stock and payment conserve both ledgers");}h.succeed();}
 @GameTest(template="empty") public static void survivingStoveCooksAfterHomeDestruction(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var family=d.state.families.get(f.person.family);f.house.beds=1;f.house.residents.add(f.worker);f.house.damaged.addAll(f.house.baseline.keySet());f.person.role=RuralRules.Role.COOK;var old=d.state.sites.values().stream().filter(v->f.worker.equals(v.worker)).findFirst().orElseThrow();d.state.sites.remove(RuralSettlement.key(old.city,old.pos));old.kind="cook";old.pos=f.wall.above().asLong();old.expectedBlock="city_settlements:rural_stove";d.state.sites.put(RuralSettlement.key(old.city,old.pos),old);h.getLevel().setBlock(f.wall.above(),RuralBlocks.STOVE.get().defaultBlockState(),3);var box=f.box();NpcStorage.box(box).stock.family=family.id;NpcStorage.box(box).linked=true;var stores=d.stocks(family.id);RuralRules.put(stores,false,4);var t=CityTrade.get(f.server);var home=new FamilyLivelihood.Home();home.processor=f.worker;home.credit=2;t.state.households.put(family.id,home);long cash=f.money();h.assertTrue(!FamilyLivelihood.home(f.city,family)&&FamilyLivelihood.stove(f.server,family)&&FamilyLivelihood.processor(f.server,family),"Real separate stove remains usable despite zero housing shell");FamilyLivelihood.cook(f.server,family);h.assertTrue(RuralRules.count(stores,true)==2&&RuralRules.count(stores,false)==2&&f.money()==cash,"Uses actual work credit and wheat once");FamilyLivelihood.cook(f.server,family);h.assertTrue(RuralRules.count(stores,true)==2,"No double spending work time");old.expectedBlock="minecraft:diamond_block";home.credit=2;h.assertTrue(!FamilyLivelihood.processor(f.server,family),"Broken stove and broken home do not supply virtual cooking");FamilyLivelihood.cook(f.server,family);h.assertTrue(RuralRules.count(stores,true)==2,"Unavailable cooking cannot transform raw food");t.state.households.remove(family.id);}h.succeed();}
}
